documents = [
    "The car needs an oil change every six months.",
    "Parking is available on level two.",
]

def keyword_search(query, documents):
    query_words = set(query.lower().split())
    for doc in documents:
        if query_words & set(doc.lower().split()):
            return doc
    return "No match found"

def semantic_search(query, documents):
    # simplified stand-in for real embedding similarity
    concept_map = {"automobile": "car", "vehicle": "car"}
    normalized_query = " ".join(concept_map.get(w, w) for w in query.lower().split())
    for doc in documents:
        if any(w in doc.lower() for w in normalized_query.split()):
            return doc
    return "No match found"

query = "automobile maintenance schedule"
print(f"Query: {query}")
print(f"Keyword search result: {keyword_search(query, documents)}")
print(f"Semantic search result: {semantic_search(query, documents)}")
